return-response.set-body:
@{
          return new JObject(
            new JProperty("error", new JObject(
              new JProperty("code", "invalid_request"),
              new JProperty("message", "The estimated prompt token count exceeds the input limit."),
              new JProperty("type", "request_error"),
              new JProperty("param", "messages"),
              new JProperty("retryable", false))),
            new JProperty("trace", new JObject(
              new JProperty("trace_id", (string)context.Variables["riversideTraceId"]),
              new JProperty("retry_count", 0)))
          ).ToString(Newtonsoft.Json.Formatting.None);
        }

retry.interval:
@{
        var fallbackSeconds = 1;
        var capSeconds = int.Parse("{{riverside-max-retry-after-seconds}}");
        if (context.Response == null)
        {
          return fallbackSeconds;
        }
        var retryAfter = context.Response.Headers.GetValueOrDefault("Retry-After", string.Empty).Trim();
        int deltaSeconds;
        if (int.TryParse(retryAfter, out deltaSeconds))
        {
          return Math.Max(1, Math.Min(capSeconds, deltaSeconds));
        }
        DateTimeOffset retryAt;
        if (DateTimeOffset.TryParse(retryAfter, out retryAt))
        {
          return Math.Max(1, Math.Min(capSeconds, (int)Math.Ceiling((retryAt - DateTimeOffset.UtcNow).TotalSeconds)));
        }
        return fallbackSeconds;
      }
